declare(strict_types=1);
namespace OCA\Mcp\Tests\Integration\Mail;
use OCA\Mcp\Tests\Integration\IntegrationTestCase;
use OCP\{Server,IDBConnection,IConfig};
use PHPUnit\Framework\Attributes\Group;
#[Group('mail')]
final class McpMailDraftIndexTest extends IntegrationTestCase {
    public function testDerivedIndexSchemaIntrospectionRetainsNativePrimaryGuard():void {
        self::assertTrue(class_exists('OCA\\Mail\\Service\\GuardedBodyIndex'),'The closed PostgreSQL index service must be installed.');$db=$this->official();$prefix=Server::get(IConfig::class)->getSystemValueString('dbtableprefix','oc_');$schema=$db->createSchema();self::assertTrue($schema->hasTable($prefix.'mail_mcp_body_index'));self::assertTrue($schema->hasTable($prefix.'mail_mcp_draft_copies'));
        $r=$db->executeQuery('SELECT indexdef FROM pg_indexes WHERE schemaname = current_schema() AND indexname = ?',[$prefix.'mail_mcp_body_fts']);try{$definition=$r->fetchOne();}finally{$r->closeCursor();}self::assertIsString($definition);self::assertStringContainsString('USING gin',strtolower($definition)===$definition?$definition:str_replace('GIN','gin',$definition));self::assertStringContainsString('to_tsvector',$definition);self::assertStringContainsString('coverage_state',$definition);
        self::assertTrue(\OCA\Mail\Db\PgDirectConnection::verified($db,Server::get(IConfig::class)));
        self::assertSame('ok',\OCA\Mail\Drafts\DraftCoordinator::forDatabase($db)->runOwner(MailActor::ALICE,static fn()=>'ok'));
    }
    public function testProtectedCopyPreservesSourceAndRetryCreatesNoSecondDraft():void {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_copy']);self::assertArrayNotHasKey('fixture_error',$r);self::assertTrue($r['copy_available']??false,'The protected native COPY service must be installed.');self::assertTrue($r['copy_exact']);self::assertTrue($r['copy_replayed']);self::assertTrue($r['source_retained']);self::assertSame(0,$r['writes']);}
    public function testExplicitBodyIndexExcludesForeignAndStaleSourcesAndPurgesChangedProfile():void {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_index_store']);self::assertArrayNotHasKey('fixture_error',$r);self::assertTrue($r['index_available']??false,json_encode($r));self::assertSame('complete',$r['coverage_state']);foreach(['found','foreign_refused','selection_bounded','unchanged_survives_sync','stale_excluded','profile_purged','quarantined','durable_refs'] as $key)self::assertTrue($r[$key],$key);self::assertSame(0,$r['writes']);self::assertSame(['1','1'],$r['body_sections']);}
    public function testTruncatedAndLongLexemeBodiesAreExplicitlyRefused():void {foreach(['large'=>'refused_size','lexeme'=>'refused_lexeme'] as $mode=>$expected){$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_index_store_'.$mode]);self::assertArrayNotHasKey('fixture_error',$r);self::assertTrue($r['index_available']??false,json_encode($r));self::assertSame($expected,$r['coverage_state']);self::assertFalse($r['found']);self::assertSame(0,$r['writes']);}}
    public function testActualFpmToolsKeepIndependentGrantsAndHistoricalReplayAfterSourceDeletion():void {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_http_draft_index']);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));foreach(['index_erased','independent_grants','cached_found','copy_succeeded','source_retained','index_succeeded','search_found','replayed_after_source_deleted','status_succeeded','revoked','private_receipt'] as $key)self::assertTrue($r[$key],$key.': '.json_encode($r));self::assertSame(0,$r['writes']);}
    public function testPostgresqlLexemeBoundaryAndBoundedVectorSize():void {$db=$this->official();foreach([2046=>false,2047=>true,2048=>true] as $bytes=>$empty){$r=$db->executeQuery("SELECT to_tsvector('simple', ?)::text AS vector",[str_repeat('x',$bytes)]);try{$v=$r->fetchOne();}finally{$r->closeCursor();}self::assertSame($empty,$v==='');}$text=implode(' ',array_map(static fn($n)=>'w'.$n,range(1,3000)));$r=$db->executeQuery("SELECT pg_column_size(to_tsvector('simple', ?)) AS bytes",[$text]);try{$size=(int)$r->fetchOne();}finally{$r->closeCursor();}self::assertGreaterThan(0,$size);self::assertLessThan(1048576,$size);}
    public function testNativeCopyRecoversLostCommitAcknowledgementWithoutRefetchOrDuplicate():void {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_copy_lost']);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));foreach(['lost_ack_recovered','copy_exact','copy_replayed','source_retained'] as $key)self::assertTrue($r[$key]??false,$key.': '.json_encode($r));self::assertSame(2,$r['connections']);self::assertSame(0,$r['writes']);}
    public function testCryptoAndUnsupportedReferencesRefuseBeforeAnyStaging():void {foreach(['crypto','unsupported'] as $mode){$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_copy_'.$mode]);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));foreach(['refused','no_staging','source_retained'] as $key)self::assertTrue($r[$key]??false,$key.': '.json_encode($r));self::assertSame(0,$r['writes']);}}
    public function testProtocolIdentityChangePurgesDerivedBody():void {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_index_store_protocol']);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));self::assertTrue($r['profile_purged']??false,json_encode($r));}
    public function testLostPrimaryLeaseBeforeIndexEffectRefusesWithoutPersisting():void {$r=MailActor::run(MailActor::ALICE,'content-native',['mode'=>'service_index_store_lease']);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));self::assertTrue($r['lease_refused']??false,json_encode($r));self::assertTrue($r['no_index_effect']??false,json_encode($r));}
}
